-- Restore reviewed recipient filtering, source-backed private timelines and explicit notification links.
-- Definitions only: no notes, broadcasts or historical data are generated by this migration.
begin;
create or replace function public.get_notification_conversations(p_section text default 'notes')
returns table (
  section text,
  conversation_key text,
  kind text,
  title text,
  subtitle text,
  avatar_url text,
  role_label text,
  note_count integer,
  unread_count integer,
  latest_message_at timestamptz,
  last_message_preview text,
  user_id uuid,
  group_id uuid,
  bot_group_id uuid,
  channel_type text,
  status text,
  counterparty_label text,
  bot_chat_id text
)
language sql
stable
security definer
set search_path = public
as $$
  with me as (
    select
      auth.uid() as user_id,
      public.current_org_id() as org_id,
      p.role_id
    from public.profiles p
    where p.id = auth.uid()
    limit 1
  ),
  note_raw as (
    select
      'notes'::text as section,
      coalesce(
        nii.conversation_key,
        nullif(trim(nii.payload->>'conversation_key'), ''),
        public.kalam_note_conversation_key(
          n.org_id,
          n.id,
          n.author_id,
          coalesce(n.mention_user_ids, '{}'::uuid[]),
          coalesce(n.source_type, n.metadata->>'source_type'),
          coalesce(n.metadata, '{}'::jsonb),
          n.reply_to
        )
      ) as conversation_key,
      lower(trim(coalesce(nii.category, ''))) as inbox_category,
      nullif(trim(coalesce(nii.payload->>'chat_group_id', n.metadata->>'chat_group_id')), '') as chat_group_id,
      n.id as note_id,
      n.author_id,
      n.created_at,
      coalesce(nullif(trim(n.author_name), ''), nullif(trim(p2.full_name), ''), n.author_id::text) as author_name,
      nullif(trim(coalesce(nii.body, '')), '') as preview,
      rs.read_at is not null or rs.dismissed_at is not null or n.author_id = me.user_id as is_read
    from me
    join public.notification_inbox_items nii
      on nii.org_id = me.org_id
     and nii.section = 'notes'
     and nii.source_type = 'note'
     -- ACCESS FILTER: only rows this user/role should see
     and (
       nii.is_org_wide = true
       or me.user_id = any(nii.target_user_ids)
       or (me.role_id is not null and me.role_id = any(nii.target_role_ids))
     )
    join public.notes n
      on n.id::text = nii.source_id
     and n.org_id = nii.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'notes'
     and rs.source_type = 'note'
     and rs.source_id = nii.source_id
    left join public.profiles p2
      on p2.id = n.author_id
    where p_section = 'notes'
  ),
  note_base as (
    select
      section,
      conversation_key,
      case
        when conversation_key like 'group:%' or chat_group_id is not null then 'group'
        when conversation_key = 'system' or inbox_category in ('system', 'assistant') then 'system'
        else 'direct'
      end as kind,
      note_id,
      author_id,
      created_at,
      author_name,
      preview,
      is_read
    from note_raw
  ),
  note_agg as (
    select
      section,
      conversation_key,
      kind,
      count(*)::integer as note_count,
      count(*) filter (where not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from note_base
    where nullif(trim(coalesce(conversation_key, '')), '') is not null
    group by section, conversation_key, kind
  ),
  note_latest as (
    select distinct on (conversation_key)
      conversation_key,
      preview
    from note_base
    where nullif(trim(coalesce(conversation_key, '')), '') is not null
    order by conversation_key, created_at desc, note_id desc
  ),
  note_enriched as (
    select
      na.section,
      na.conversation_key,
      na.kind,
      case
        when na.kind = 'system' then 'پیام‌های سیستم'
        when na.kind = 'group' then coalesce(cg.name, 'گروه')
        else coalesce(other_profile.full_name, other_profile.id::text, split_part(na.conversation_key, ':', 3))
      end as title,
      case
        when na.kind = 'group' then 'گروه داخلی'
        when na.kind = 'direct' then coalesce(other_role.title, null)
        else null
      end as subtitle,
      case when na.kind = 'direct' then other_profile.avatar_url else null end as avatar_url,
      case when na.kind = 'direct' then other_role.title else null end as role_label,
      na.note_count,
      na.unread_count,
      na.latest_message_at,
      nl.preview as last_message_preview,
      case
        when na.kind = 'direct' then
          case
            when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
              then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
            else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
          end
        else null
      end as user_id,
      case when na.kind = 'group'
        then public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
        else null
      end as group_id,
      null::uuid as bot_group_id,
      null::text as channel_type,
      null::text as status,
      null::text as counterparty_label,
      null::text as bot_chat_id
    from note_agg na
    join me on true
    left join note_latest nl
      on nl.conversation_key = na.conversation_key
    left join public.chat_groups cg
      on na.kind = 'group'
     and cg.id = public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
    left join public.profiles other_profile
      on na.kind = 'direct'
     and other_profile.id = (
       case
         when public.kalam_try_uuid(split_part(na.conversation_key, ':', 2)) = me.user_id
           then public.kalam_try_uuid(split_part(na.conversation_key, ':', 3))
         else public.kalam_try_uuid(split_part(na.conversation_key, ':', 2))
       end
     )
    left join public.org_roles other_role
      on other_role.id = other_profile.role_id
  ),
  bot_base as (
    select
      'bot_messages'::text as section,
      'bot:' || g.id::text as conversation_key,
      'bot'::text as kind,
      g.id as bot_group_id,
      g.group_title,
      g.channel_type,
      g.status,
      g.bot_chat_id,
      g.customer_id,
      g.supplier_id,
      m.id as message_id,
      m.created_at,
      coalesce(nullif(trim(m.content_text), ''), nullif(trim(m.file_name), ''), nullif(trim(m.message_type), '')) as preview,
      m.direction,
      rs.read_at is not null or rs.dismissed_at is not null or m.direction <> 'inbound' as is_read
    from me
    join public.counterparty_bot_groups g
      on g.org_id = me.org_id
    left join public.counterparty_bot_messages m
      on m.bot_group_id = g.id
     and m.org_id = g.org_id
    left join public.notification_read_states rs
      on rs.org_id = me.org_id
     and rs.user_id = me.user_id
     and rs.section = 'bot_messages'
     and rs.source_type = 'counterparty_bot_message'
     and rs.source_id = m.id::text
    where p_section = 'bot_messages'
      and (
        (
          coalesce(jsonb_array_length(g.metadata->'allowed_user_ids'), 0) = 0
          and coalesce(jsonb_array_length(g.metadata->'allowed_role_ids'), 0) = 0
        )
        or me.user_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_user_ids'))
        or (me.role_id is not null and me.role_id = any(public.kalam_jsonb_uuid_array(g.metadata->'allowed_role_ids')))
      )
  ),
  bot_agg as (
    select
      section,
      conversation_key,
      kind,
      bot_group_id,
      min(group_title) as title,
      min(channel_type) as channel_type,
      min(status) as status,
      min(bot_chat_id) as bot_chat_id,
      count(message_id)::integer as note_count,
      count(message_id) filter (where direction = 'inbound' and not is_read)::integer as unread_count,
      max(created_at) as latest_message_at
    from bot_base
    group by section, conversation_key, kind, bot_group_id
  ),
  bot_latest as (
    select distinct on (conversation_key)
      conversation_key,
      preview
    from bot_base
    where message_id is not null
    order by conversation_key, created_at desc, message_id desc
  ),
  bot_enriched as (
    select
      ba.section,
      ba.conversation_key,
      ba.kind,
      coalesce(nullif(trim(ba.title), ''), 'گروه بات') as title,
      case
        when g.customer_id is not null then coalesce(c.full_name, c.business_name, c.legal_name, c.system_code)
        when g.supplier_id is not null then coalesce(s.business_name, s.full_name, s.system_code)
        else null
      end as subtitle,
      null::text as avatar_url,
      null::text as role_label,
      ba.note_count,
      ba.unread_count,
      ba.latest_message_at,
      bl.preview as last_message_preview,
      null::uuid as user_id,
      null::uuid as group_id,
      ba.bot_group_id,
      ba.channel_type,
      ba.status,
      case
        when g.customer_id is not null then coalesce(c.full_name, c.business_name, c.legal_name, c.system_code)
        when g.supplier_id is not null then coalesce(s.business_name, s.full_name, s.system_code)
        else null
      end as counterparty_label,
      ba.bot_chat_id
    from bot_agg ba
    join public.counterparty_bot_groups g
      on g.id = ba.bot_group_id
    left join bot_latest bl
      on bl.conversation_key = ba.conversation_key
    left join public.customers c
      on c.id = g.customer_id
    left join public.suppliers s
      on s.id = g.supplier_id
  )
  select * from note_enriched
  union all
  select * from bot_enriched
  order by latest_message_at desc nulls last, title asc;
$$;
create or replace function public.get_internal_conversation_timeline_v2(
  p_conversation_key text,
  p_limit integer default 20,
  p_before_cursor text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_org_id uuid := public.current_org_id();
  v_role_id uuid := null;
  v_key text := nullif(trim(coalesce(p_conversation_key, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_before_ts timestamptz := null;
  v_before_id text := null;
  v_direct_left uuid := null;
  v_direct_right uuid := null;
begin
  if v_user_id is null or v_org_id is null or v_key is null then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  select profile.role_id
    into v_role_id
  from public.profiles profile
  where profile.id = v_user_id
    and profile.org_id = v_org_id
  limit 1;

  if v_key like 'direct:%' then
    v_direct_left := public.kalam_try_uuid(split_part(v_key, ':', 2));
    v_direct_right := public.kalam_try_uuid(split_part(v_key, ':', 3));
    if v_direct_left is null
       or v_direct_right is null
       or (v_user_id <> v_direct_left and v_user_id <> v_direct_right) then
      return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
    end if;
  elsif v_key <> 'mine' and v_key <> 'system' and v_key not like 'group:%' then
    return jsonb_build_object('items', '[]'::jsonb, 'unread_count', 0, 'first_unread_id', null, 'has_more_before', false, 'next_before_cursor', null, 'read_model', 'cursor');
  end if;

  if nullif(trim(coalesce(p_before_cursor, '')), '') is not null then
    v_before_ts := nullif(split_part(p_before_cursor, '|', 1), '')::timestamptz;
    v_before_id := nullif(split_part(p_before_cursor, '|', 2), '');
  end if;

  return (
    with source_notes as materialized (
      select n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notes n
      where v_key like 'direct:%'
        and n.org_id = v_org_id
        and n.author_id in (v_direct_left, v_direct_right)
        and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
        and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
        and (
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          ) = v_key
          or (
            n.author_id = case when v_user_id = v_direct_left then v_direct_right else v_direct_left end
            and (
              v_user_id = any(coalesce(n.mention_user_ids, '{}'::uuid[]))
              or (
                v_role_id is not null
                and v_role_id = any(coalesce(n.mention_role_ids, '{}'::uuid[]))
              )
            )
          )
        )
        and public.kalam_can_access_note(
          n.id, n.author_id, n.org_id, n.mention_user_ids, n.mention_role_ids, n.reply_to, coalesce(n.metadata, '{}'::jsonb)
        )

      union all

      select n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notes n
      where v_key = 'mine'
        and n.org_id = v_org_id
        and n.author_id = v_user_id
        and nullif(trim(coalesce(n.metadata->>'chat_group_id', '')), '') is null
        and lower(trim(coalesce(n.source_type, n.metadata->>'source_type', ''))) not in ('system', 'ai')
        and not (coalesce(n.metadata, '{}'::jsonb) ?| array['workflow_id', 'automation_rule_id', 'process_automation_rule_id'])
        and (
          lower(trim(coalesce(n.metadata->>'saved_message', 'false'))) in ('true', '1', 'yes')
          or cardinality(coalesce(n.mention_user_ids, '{}'::uuid[])) = 0
        )

      union all

      (
      select distinct on (n.id)
        n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notification_inbox_items inbox
      join public.notes n
        on n.id::text = inbox.source_id
       and n.org_id = inbox.org_id
      where v_key = 'system'
        and inbox.org_id = v_org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and lower(trim(coalesce(inbox.category, ''))) in ('system', 'assistant')
        and coalesce(
          inbox.conversation_key,
          nullif(trim(inbox.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          )
        ) = v_key
        and (
          inbox.is_org_wide = true
          or v_user_id = any(inbox.target_user_ids)
          or (v_role_id is not null and v_role_id = any(inbox.target_role_ids))
        )
      order by n.id, n.created_at desc
      )

      union all

      (
      select distinct on (n.id)
        n.id, n.module_id, n.record_id, n.content, n.author_id, n.author_name,
        n.mention_user_ids, n.mention_role_ids, n.created_at, n.reply_to, n.source_type,
        n.metadata, n.is_edited, n.edited_at
      from public.notification_inbox_items inbox
      join public.notes n
        on n.id::text = inbox.source_id
       and n.org_id = inbox.org_id
      where v_key like 'group:%'
        and inbox.org_id = v_org_id
        and inbox.section = 'notes'
        and inbox.source_type = 'note'
        and coalesce(
          inbox.conversation_key,
          nullif(trim(inbox.payload->>'conversation_key'), ''),
          public.kalam_note_conversation_key(
            n.org_id, n.id, n.author_id, coalesce(n.mention_user_ids, '{}'::uuid[]),
            coalesce(n.source_type, n.metadata->>'source_type'), coalesce(n.metadata, '{}'::jsonb), n.reply_to
          )
        ) = v_key
        and (
          inbox.is_org_wide = true
          or v_user_id = any(inbox.target_user_ids)
          or (v_role_id is not null and v_role_id = any(inbox.target_role_ids))
        )
      order by n.id, n.created_at desc
      )
    ),
    visible as materialized (
      select source_notes.*,
        (
          source_notes.author_id = v_user_id
          or read_state.read_at is not null
          or read_state.dismissed_at is not null
          or (
            cursor_state.read_through_at is not null
            and (
              source_notes.created_at < cursor_state.read_through_at
              or (
                source_notes.created_at = cursor_state.read_through_at
                and source_notes.id::text <= coalesce(cursor_state.read_through_id, source_notes.id::text)
              )
            )
          )
        ) as is_read
      from source_notes
      left join public.notification_read_states read_state
        on read_state.org_id = v_org_id
       and read_state.user_id = v_user_id
       and read_state.section = 'notes'
       and read_state.source_type = 'note'
       and read_state.source_id = source_notes.id::text
      left join public.communication_read_cursors cursor_state
        on cursor_state.org_id = v_org_id
       and cursor_state.user_id = v_user_id
       and cursor_state.channel = 'internal'
       and cursor_state.conversation_key = v_key
    ),
    unread as (
      select count(*) filter (where not is_read)::integer as unread_count
      from visible
    ),
    windowed as (
      select *
      from visible
      where v_before_ts is null
         or created_at < v_before_ts
         or (created_at = v_before_ts and id::text < coalesce(v_before_id, ''))
      order by created_at desc, id desc
      limit v_limit + 1
    ),
    page_desc as (
      select * from windowed order by created_at desc, id desc limit v_limit
    ),
    page as (
      select * from page_desc order by created_at asc, id asc
    ),
    earliest as (
      select created_at, id::text as id_text from page order by created_at asc, id asc limit 1
    )
    select jsonb_build_object(
      'items', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at asc, page.id asc) from page), '[]'::jsonb),
      'unread_count', coalesce((select unread_count from unread), 0),
      'first_unread_id', (select id::text from page where not is_read order by created_at asc, id asc limit 1),
      'has_more_before', (select count(*) > v_limit from windowed),
      'next_before_cursor', (select public.kalam_cursor_value(created_at, id_text) from earliest),
      'read_model', 'cursor'
    )
  );
end;
$$;
create or replace function public.kalam_emit_notification_item()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payload jsonb;
  v_user_id uuid;
  v_role_id uuid;
begin
  v_payload := jsonb_build_object(
    'id', new.id,
    'org_id', new.org_id,
    'source_type', new.source_type,
    'source_id', new.source_id,
    'section', new.section,
    'category', new.category,
    'action', new.action,
    'module_id', new.module_id,
    'record_id', new.record_id,
    'last_event_at', new.last_event_at,
    'targeted', not new.is_org_wide
  );

  if new.is_org_wide then
    perform public.kalam_broadcast_notification(public.kalam_realtime_org_topic(new.org_id), 'notification', v_payload);
  end if;

  foreach v_user_id in array public.kalam_distinct_uuid_array(new.target_user_ids) loop
    perform public.kalam_broadcast_notification(public.kalam_realtime_user_topic(new.org_id, v_user_id), 'notification', v_payload);
  end loop;

  foreach v_role_id in array public.kalam_distinct_uuid_array(new.target_role_ids) loop
    perform public.kalam_broadcast_notification(public.kalam_realtime_role_topic(new.org_id, v_role_id), 'notification', v_payload);
  end loop;

  return new;
end;
$$;
revoke all on function public.get_notification_conversations(text) from public,anon;
grant execute on function public.get_notification_conversations(text) to authenticated;
revoke all on function public.get_internal_conversation_timeline_v2(text,integer,text) from public,anon;
grant execute on function public.get_internal_conversation_timeline_v2(text,integer,text) to authenticated;
revoke all on function public.kalam_emit_notification_item() from public,anon,authenticated;
notify pgrst,'reload schema';
commit;
